#!/bin/bash
set -e

echo "=== Sostituisco l'icona dell'app (pesce + libro) ==="

mkdir -p public/icons

base64 -d > public/icons/icon-512.png << 'ICON512PNGEOF'

ICON512PNGEOF

base64 -d > public/icons/icon-192.png << 'ICON192PNGEOF'

ICON192PNGEOF

base64 -d > public/icons/apple-touch-icon.png << 'APPLETOUCHICONPNGEOF'

APPLETOUCHICONPNGEOF

echo "=== Icone aggiornate: ==="
echo "  public/icons/icon-512.png"
echo "  public/icons/icon-192.png"
echo "  public/icons/apple-touch-icon.png"
echo ""
echo "Ricorda: bash nuova-icona-app.sh, poi:"
echo "git add -A && git commit -m 'aggiorna icona app: pesce + libro' && git push"
